export function normalizeInterceptedTurnResult(input: {
  result: unknown;
  model: string;
  inputCharacters: number;
}): InterceptedTurnResult {
  const { result, model } = input;
  const asObject =
    typeof result === "string"
      ? { text: result }
      : ((result || {}) as { text?: unknown; usage?: unknown });
  if (typeof asObject.text !== "string") {
    throw new Error(
      `AI interceptor returned a non-text agent-turn result for "${model}": expected a string or { text, usage? }, got ${JSON.stringify(result)?.slice(0, 200)}`,
    );
  }
  const estimate = (characters: number) => Math.ceil(characters / 4);
  const usage = asObject.usage as InterceptedTurnResult["usage"] | undefined;
  return {
    text: asObject.text,
    usage: usage || {
      inputTokens: estimate(input.inputCharacters),
      outputTokens: estimate(asObject.text.length),
    },
  };
}

export function threadContextForScriptRun(
  events: StreamEvent[],
  run: { executionId: string },
): { title: string | null; activity: string | null } | null {
  const ordered = [...events].sort((a, b) => a.offset - b.offset);
  const settle = ordered.find(
    (event) =>
      event.type === SCRIPT_RUN_SETTLED_TYPE &&
      (event.payload as { executionId?: string } | undefined)?.executionId === run.executionId,
  );
  const statusBound = settle === undefined ? Infinity : settle.offset;
  let title: string | null = null;
  let activity: string | null = null;
  for (const event of ordered) {
    if (event.type !== SUMMARY_UPDATED_TYPE || event.offset > statusBound) continue;
    const payload = (event.payload || {}) as { title?: string | null; activity?: string | null };
    if (payload.title !== undefined) title = payload.title || null;
    if (payload.activity !== undefined) activity = payload.activity || null;
  }
  return title !== null || activity !== null ? { title, activity } : null;
}

function parseArgs(argv: string[]) {
  const command = argv[0] as Command;
  if (!COMMANDS.includes(command)) throw new Error(USAGE);
  let pr: string | undefined;
  let name: string | undefined;
  let dryRun = false;
  for (let i = 1; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === "--dry-run") dryRun = true;
    else if (arg === "--pr") pr = argv[++i];
    else if (arg === "--name") name = argv[++i];
    else throw new Error(`unknown argument: ${arg}\n${USAGE}`);
  }
  return { command, pr, name, dryRun };
}

