export function captionForEvent(type: string, payload: unknown): string | null {
  const p = (payload ?? {}) as Record<string, unknown>;
  switch (type) {
    case EVENT.callStarted:
    case EVENT.conversationAccepted:
      /* Lifecycle captions are LOCAL state (ringing / hold to talk /
       * listening) — the accepted event lands mid-first-hold and must not
       * overwrite "listening…" under the caller's thumb. */
      return null;
    case EVENT.colleagueStatus: {
      const status =
        (typeof p.activity === "string" && p.activity) || (typeof p.phase === "string" && p.phase);
      return status ? `backend: ${status}` : null;
    }
    case EVENT.colleagueNote:
      return typeof p.text === "string" && p.text !== ""
        ? `backend: ${p.text.length > 90 ? `${p.text.slice(0, 90)}…` : p.text}`
        : null;
    case EVENT.conversationEnded:
      return typeof p.reason === "string" && p.reason !== ""
        ? `call ended — ${p.reason}`
        : "call ended";
    default:
      return null;
  }
}

export async function listIntegrationConnections(
  projectId: string,
): Promise<{ connection: string; integration: string; path: string }[]> {
  // The project processor runs as a facet of the root stream; its facade
  // serves the catch-up-backed snapshot.
  const facade = await itxEnv.STREAM.getByName(
    DurableObjectNameCodec.stringify({ projectId, path: "/" }),
  ).processorFacade({ name: ProjectProcessorContract.slug });
  const snapshot = await facade.snapshot();
  const state = snapshot.state as ProjectProcessorState;
  const entries: { connection: string; integration: string; path: string }[] = [];
  for (const stream of state.streams) {
    const coordinates = integrationCoordinatesFromStreamPath(stream.path);
    if (coordinates === null) continue;
    entries.push({
      connection: coordinates.connection,
      integration: coordinates.slug,
      path: stream.path,
    });
  }
  return entries;
}

async function execRunner(options: LiveProbeOptions): Promise<(code: string) => Promise<string>> {
  if (!options.project) throw new Error("--exec needs --project");
  const itx = await connectProject({
    project: options.project,
    ...(options.baseUrl === undefined ? {} : { baseUrl: options.baseUrl }),
  });
  return async (code: string) => {
    try {
      const fn = new AsyncFunction("itx", `return await (${code})(itx);`);
      const timedOut = Symbol("exec deadline");
      const result = await Promise.race([fn(itx), sleep(60_000).then(() => timedOut as unknown)]);
      if (result === timedOut)
        return JSON.stringify({ error: "exec_typescript took longer than 60s" });
      const json = JSON.stringify(result ?? null);
      return json.length > 8_000 ? JSON.stringify({ truncated: json.slice(0, 8_000) }) : json;
    } catch (error) {
      return JSON.stringify({ error: String(error).slice(0, 1_000) });
    }
  };
}

export async function ensureApproverKeyEnrolled(
  baseUrl: string,
  projectId: string,
): Promise<ApproverKeyInfo | null> {
  const key = await enrollApproverKey(
    projectId,
    Platform.OS === "web" ? "This browser (dev)" : "This iPhone",
  );
  const project = await getProjectItx(baseUrl, projectId);
  const enrolled = (await project.processor.snapshot()).state.humanApprovalKeys as Array<{
    keyId: string;
    revokedAt: string | null;
  }>;
  const existing = enrolled.find((candidate) => candidate.keyId === key.keyId);
  if (existing) return existing.revokedAt === null ? key : null;
  await project.streams.get("/").append({
    type: EVENT.keyAdded,
    payload: { keyId: key.keyId, publicKey: key.publicKey, label: key.label },
  });
  return key;
}

