export async function refreshProjectSession(input: {
  fetch: (url: string, init: RequestInit) => Promise<Response>;
  returnTo: string;
}): Promise<RefreshOutcome> {
  const url = `${PROJECT_AUTH_REFRESH_PATH}?${new URLSearchParams({ return_to: input.returnTo })}`;
  let response: Response;
  try {
    response = await input.fetch(url, { credentials: "same-origin", method: "POST" });
  } catch {
    return { outcome: "unavailable" };
  }
  if (response.status === 401) {
    let login = loginPathFor(input.returnTo);
    try {
      const body: unknown = await response.json();
      if (typeof body === "object" && body !== null && "login" in body) {
        const pointer = (body as { login: unknown }).login;
        if (typeof pointer === "string" && pointer.startsWith("/")) login = pointer;
      }
    } catch {
      // A bare 401 still means signed out; the pointer is a courtesy.
    }
    return { outcome: "signed-out", login };
  }
  if (!response.ok) return { outcome: "unavailable" };
  try {
    const body: unknown = await response.json();
    const expiresAt =
      typeof body === "object" && body !== null && "expiresAt" in body
        ? (body as { expiresAt: unknown }).expiresAt
        : undefined;
    if (typeof expiresAt !== "number") return { outcome: "unavailable" };
    return { outcome: "renewed", expiresAt };
  } catch {
    return { outcome: "unavailable" };
  }
}

function upsertAuthSeedOAuthClient(client: SeedOAuthClientSpec) {
  const raw = getDopplerSecret("auth", "prd", "AUTH_SEED_OAUTH_CLIENTS");
  const clients: SeedOAuthClientSpec[] = raw ? (JSON.parse(raw) as SeedOAuthClientSpec[]) : [];
  const index = clients.findIndex(
    (candidate) =>
      candidate.referenceId === client.referenceId || candidate.clientId === client.clientId,
  );
  if (index === -1) clients.push(client);
  else clients[index] = client;
  clients.sort((a, b) => (a.referenceId ?? a.clientId).localeCompare(b.referenceId ?? b.clientId));
  setDopplerSecrets("auth", "prd", { AUTH_SEED_OAUTH_CLIENTS: JSON.stringify(clients) });
  console.log("auth/prd AUTH_SEED_OAUTH_CLIENTS updated");
}

function admitLoadedCodeExpression(expression: ItxExpression, base: string): void {
  let at = base;
  for (const step of expression) {
    const name = typeof step === "string" ? step : step[0];
    if (name === "builtins")
      throw codedError(
        "FORBIDDEN",
        `"itx.builtins" is not a loaded worker's word — this context's rows say what its code may spell (${JSON.stringify(print(expression, { holes: true }))})`,
      );
    if (Array.isArray(step))
      for (const arg of step.slice(1)) {
        const source = typeof arg === "object" && arg && "source" in arg ? arg.source : undefined;
        if (typeof source === "string" || Array.isArray(source))
          admitLoadedCodeExpression(normalizedItxExpression(source), at);
      }
    if (Array.isArray(step) && step[0] === "cd" && typeof step[1] === "string") {
      const to = resolveContextPath(at, step[1]);
      if (to !== at && !to.startsWith(at === "/" ? "/" : `${at}/`))
        throw codedError(
          "FORBIDDEN",
          `cd goes down only for loaded code: ${JSON.stringify(step[1])} from ${JSON.stringify(at)} would leave it`,
        );
      at = to;
    }
  }
}

