export function sentenceText(node: ReactNode): string {
  if (node === null || node === undefined || typeof node === "boolean") return "";
  if (typeof node === "string" || typeof node === "number") return String(node);
  if (Array.isArray(node)) return node.map(sentenceText).join("");
  if (isValidElement<{ children?: ReactNode }>(node)) return sentenceText(node.props.children);
  return "";
}

function isPlainLiteral(init: any) {
  if (init.type === "Literal") {
    return typeof init.value === "number" || typeof init.value === "string";
  }
  if (init.type === "TemplateLiteral") return init.expressions.length === 0;
  if (init.type === "UnaryExpression" && init.operator === "-") {
    return init.argument.type === "Literal" && typeof init.argument.value === "number";
  }
  return false;
}

function decodeRpcStubPagerAttachRequest(header: string): RpcStubPagerAttachRequest {
  const decoded = JSON.parse(decodeURIComponent(header)) as Partial<RpcStubPagerAttachRequest>;
  // oxlint-disable-next-line iterate/simple-truthiness-check -- runtime validation of JSON.parse output; the `Partial<...>` cast is a claim, not a guarantee
  if (typeof decoded?.rpcStubKey !== "string" || !Array.isArray(decoded.appendEvents))
    throw new Error("expected { rpcStubKey: string, appendEvents: [] }");
  return { rpcStubKey: decoded.rpcStubKey, appendEvents: decoded.appendEvents };
}

export function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && !!value && !Array.isArray(value);
}

function parseSubscriptionName(name: string): string {
  // oxlint-disable-next-line iterate/simple-truthiness-check -- runtime validation of a name carried in an untrusted event payload (the `: string` type is a claim); the typeof guards the pattern test and prototype-pollution check below
  if (typeof name !== "string" || !SUBSCRIPTION_NAME_PATTERN.test(name) || name in Object.prototype)
    throw new Error(
      `a subscription name is one segment: [A-Za-z0-9_-]+, never a key of Object.prototype (got ${JSON.stringify(name)})`,
    );
  if (name === CoreContract.slug)
    throw new Error(
      `"${CoreContract.slug}" is reserved as a subscription name: it is the core reduce, never a configurable subscription`,
    );
  return name;
}

function jsonFromBase64UrlSegment(segment: string): Record<string, unknown> | null {
  try {
    const parsed = JSON.parse(new TextDecoder().decode(bytesFromBase64Url(segment)));
    return typeof parsed === "object" && parsed !== null
      ? (parsed as Record<string, unknown>)
      : null;
  } catch {
    return null;
  }
}

export function githubInstallationIdOf(payload: Record<string, unknown>): string | null {
  const id = isRecord(payload.installation) ? payload.installation.id : undefined;
  return typeof id === "number" || (typeof id === "string" && id) ? String(id) : null;
}

function derefInternal(root: unknown, node: unknown, seen = new Set<string>()): unknown {
  while (
    node != null &&
    // oxlint-disable-next-line iterate/simple-truthiness-check -- node is untrusted JSON (unknown); after the null check it narrows to {} but may still be a string/number, so typeof-object is real validation before reading .$ref
    typeof node === "object" &&
    typeof (node as { $ref?: unknown }).$ref === "string"
  ) {
    const ref = (node as { $ref: string }).$ref;
    if (seen.has(ref)) return undefined; // a ref cycle resolves to nothing, never a hang
    seen.add(ref);
    node = resolveInternalRef(root, ref);
  }
  return node;
}

export function isSecretOAuthState(claims: unknown): claims is SecretOAuthState {
