function probe(dopplerConfig: string, ceilingDoHours: number) {
  let stdout = "";
  let stderr = "";
  try {
    stdout = execFileSync(
      "doppler",
      // prettier-ignore
      [
        "run", "--project", "os", "--config", dopplerConfig, "--",
        "pnpm", "tsx", "scripts/monitors/do-duration-probe.ts",
        "--hours", String(LOOKBACK_HOURS), "--max-account-do-hours", String(ceilingDoHours), "--json",
      ],
      { encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] },
    );
  } catch (error: any) {
    // The probe exits non-zero on a breach AND on a crash; the summary line
    // below tells them apart.
    stdout = error.stdout || "";
    stderr = error.stderr || "";
  }
  if (stderr) console.error(stderr);
  const lastLine = stdout.trim().split("\n").at(-1) || "";
  try {
    // The probe's --json contract: its LAST stdout line is one ProbeSummary
    // (scripts/monitors/do-duration-probe.ts prints it after the human report
    // moves to stderr). Anything else — a crash before the summary, a stray
    // line — fails JSON.parse and is reported as a probe failure, so a wrong
    // shape cannot masquerade as a clean account.
    return { summary: JSON.parse(lastLine) as ProbeSummary, failure: null };
  } catch {
    const reason = stderr.trim().split("\n").filter(Boolean).at(-1) || "printed no summary";
    return { summary: null, failure: reason.slice(0, 200) };
  }
}

export function ingressRouting(): IngressRouting {
  const routing = process.env.PROJECT_INGRESS_ROUTING;
  if (!routing)
    throw new Error("PROJECT_INGRESS_ROUTING unset — the e2e globalSetup/setup did not run");
  return JSON.parse(routing) as IngressRouting;
}

export function itxAnswerDetachedFromSession(
  result: unknown,
  expression: ItxExpression,
  args: unknown[] = [],
): unknown {
  const last = expression.at(-1);
  const reference: ItxHandleReference = {
    [ITX_HANDLE_REFERENCE_KEY]:
      args.length === 0
        ? expression
        : typeof last === "string" && expression.length > 1
          ? [...expression.slice(0, -1), [last, ...args]]
          : [...expression, ["", ...args]],
  };
  if (holdsRpcSession(result)) {
    releaseRpcSessions([result]);
    return reference;
  }
  if (result instanceof RpcTarget || typeof result === "function" || isItxHandleReference(result))
    return reference;
  if (!isRpcResultWithDisposer(result)) return result;
  let copy: unknown;
  try {
    copy = structuredClone(result);
  } catch {
    return result; // a stream, a Response, data holding a stub: not data a copy can carry
  }
  releaseRpcSessions([result]);
  return copy;
}

function resolveInternalRef(root: unknown, ref: string): unknown {
  if (!ref.startsWith("#/")) return undefined;
  let node: unknown = root;
  for (const segment of ref
    .slice(2)
    .split("/")
    .map((s) => s.replace(/~1/g, "/").replace(/~0/g, "~"))) {
    // oxlint-disable-next-line iterate/simple-truthiness-check -- node is untrusted JSON (unknown); after the null check it narrows to {} but may still be a string/number, so typeof-object is real validation before indexing
    if (node == null || typeof node !== "object") return undefined;
    node = (node as Record<string, unknown>)[segment];
  }
  return node;
}

async function lockedDependencyGraph(
  specifiers: string[],
  dependencies: Record<string, string>,
  opts: ResolveOptions,
): Promise<DependencyGraph> {
  const packages = [...new Set(specifiers.map(packageName))].sort();
  const lockInput = {
    specifiers,
    ranges: Object.fromEntries(packages.map((name) => [name, dependencies[name]!])),
    externals: [...WORKERD_BUILTINS, ...platformPackages(opts.platform)],
  };
  // The prefix names the lock's shape and the rewrite rules: a change to either is a new prefix.
  const key = `module-lock-1/${await sha256(JSON.stringify(lockInput))}`;
  const stored = await opts.store.get(key);
  if (stored) return JSON.parse(stored) as DependencyGraph;
  const graph = await resolveFromEsm(lockInput, opts);
  await opts.store.put(key, JSON.stringify(graph));
  return graph;
}

async function prPublishesPackages(pr: string): Promise<boolean> {
  const repository = process.env.GITHUB_REPOSITORY?.trim() || "iterate/iterate";
  const token = process.env.GITHUB_TOKEN?.trim();
  const globs = publishPaths();
  for (let page = 1; ; page++) {
    const response = await fetch(
      `https://api.github.com/repos/${repository}/pulls/${pr}/files?per_page=100&page=${page}`,
      { headers: token ? { authorization: `Bearer ${token}` } : {} },
    );
    if (!response.ok) throw new Error(`GitHub listed PR ${pr}'s files with ${response.status}`);
    const files = (await response.json()) as { filename: string }[];
    if (files.some(({ filename }) => globs.some((glob) => matchesGlob(filename, glob))))
      return true;
    if (files.length < 100) return false;
  }
}

