function pickPort(requested: number | undefined, used: Set<number>): number {
  if (requested !== undefined) {
    if (used.has(requested)) throw new Error(`port ${requested} is taken`);
    return requested;
  } else {
    let port = 8000;
    while (used.has(port)) port++;
    return port;
  }
}

