function applyPatch(doc: Doc, patch: Patch): Doc {
  if (patch.baseRev !== doc.rev) {
    throw new Error(`patch is for rev ${patch.baseRev}, doc is at ${doc.rev}`);
  } else {
    const next = structuredClone(doc);
    for (const op of patch.ops) applyOp(next, op);
    next.rev = doc.rev + 1;
    return next;
  }
}

