}

function split(events: StreamEvent[]) {
  const durable: StreamEvent[] = [];
  const ephemeral: StreamEvent[] = [];
  for (const event of events) {
    if (event.ephemeral) ephemeral.push(event);
    else durable.push(event);
  }
  return { durable, ephemeral };
}

